void thaydoi(int n){
    n += 100;
}

int main(){
    int m = 1000;
    thaydoi(m);
    cout << m;   // vẫn là 1000
}

void thaydoi(int &n){
    n += 100;
}

int main(){
    int m = 1000;
    thaydoi(m);
    cout << m;   // thành 1100
}

void swap1(int a, int b){ int t=a; a=b; b=t; }
void swap2(int &a, int &b){ int t=a; a=b; b=t; }

int x=100, y=200;
swap1(x, y); // x=100 y=200 (không đổi)
swap2(x, y); // x=200 y=100 (đổi thật)
